    print("jsonschema unavailable — skipping schema validation"); sys.exit(0)

# Load CRD schemas for the kinds we hand-wrote
schemas={}
for f in glob.glob(os.path.join(sp,"openchoreo-control-plane/crds/*.yaml"))+glob.glob(os.path.join(sp,"kgateway-crds/templates/*.yaml")):
    for d in yaml.safe_load_all(open(f)):
        if not d or d.get("kind")!="CustomResourceDefinition": continue
        kind=d["spec"]["names"]["kind"]
        schemas[kind]=d["spec"]["versions"][0]["schema"]["openAPIV3Schema"]

def strip(s):
    # openAPIV3Schema uses x-kubernetes-* extensions jsonschema doesn't know
    if isinstance(s,dict):
        return {k:strip(v) for k,v in s.items() if not k.startswith("x-kubernetes")}
    if isinstance(s,list): return [strip(x) for x in s]
    return s

bad=0
for f in ["registration/clusterplanes.yaml","kgateway-params/gatewayparameters.yaml"]:
    for d in yaml.safe_load_all(open(f)):
        if not d: continue
        k=d["kind"]
        if k not in schemas: print(f"  {k}: no schema found, skipped"); continue
        errs=sorted(Draft7Validator(strip(schemas[k])).iter_errors(d), key=lambda e:e.path)
        if errs:
            bad=1
            for e in errs[:6]: print(f"  ✗ {k}/{d['metadata']['name']}: {'.'.join(map(str,e.path))}: {e.message[:160]}")
        else:
            print(f"  ✓ {k}/{d['metadata']['name']} validates against its v1.2.1 CRD schema")
sys.exit(bad)
